/*
  LILYGO T-Embed CC1101 - test wyswietlacza ST7789
  Testuje tylko zasilanie plytki, podswietlenie i ekran.
  Nie uruchamia CC1101 ani Wi-Fi.
*/

// Konfiguracja TFT_eSPI zgodna z oficjalnym Setup214 LilyGO.
#define USER_SETUP_LOADED
#define ST7789_DRIVER
#define TFT_WIDTH  170
#define TFT_HEIGHT 320
#define USE_HSPI_PORT
#define TFT_INVERSION_ON

#define TFT_BL   21
#define TFT_MISO 10
#define TFT_MOSI 9
#define TFT_SCLK 11
#define TFT_CS   41
#define TFT_DC   16
#define TFT_RST  -1

#define SPI_FREQUENCY 40000000
#define SPI_READ_FREQUENCY 20000000

#include <Arduino.h>
#include <TFT_eSPI.h>

TFT_eSPI tft = TFT_eSPI();

void setup() {
  Serial.begin(115200);
  delay(300);

  Serial.println();
  Serial.println("T-Embed CC1101 - DISPLAY TEST");

  // Wlacz zasilanie ukladow na plytce.
  pinMode(15, OUTPUT);
  digitalWrite(15, HIGH);
  delay(100);

  // Wlacz podswietlenie ekranu.
  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);
  delay(100);

  Serial.println("Power enabled, backlight enabled");
  Serial.println("Initialising ST7789...");

  tft.init();
  tft.setRotation(3);
  tft.fillScreen(TFT_BLACK);

  Serial.printf("Display size: %d x %d\n", tft.width(), tft.height());

  // Plansza 1: kolory podstawowe.
  int w = tft.width();
  int h = tft.height();
  tft.fillRect(0, 0, w / 3, h, TFT_RED);
  tft.fillRect(w / 3, 0, w / 3, h, TFT_GREEN);
  tft.fillRect(2 * w / 3, 0, w - 2 * (w / 3), h, TFT_BLUE);
  delay(1800);

  // Plansza 2: tekst kontrolny.
  tft.fillScreen(TFT_BLACK);
  tft.setTextColor(TFT_WHITE, TFT_BLACK);
  tft.setTextDatum(MC_DATUM);
  tft.drawString("LILYGO", w / 2, h / 2 - 28, 4);
  tft.drawString("DISPLAY OK", w / 2, h / 2 + 8, 4);
  tft.drawString("ST7789  320x170", w / 2, h / 2 + 38, 2);

  Serial.println("If you can read DISPLAY OK, the screen test passed.");
}

void loop() {
  static uint32_t last = 0;
  static bool invert = false;

  if (millis() - last >= 1000) {
    last = millis();
    invert = !invert;
    tft.drawRect(0, 0, tft.width(), tft.height(),
                 invert ? TFT_YELLOW : TFT_CYAN);
    Serial.println("Display test running");
  }
}
